import { describe, expect, it } from '@jest/globals';

import {
  MAGIC_WINDOW_SEC,
  checkRotatingQr,
  parseRotatingQr,
  verifyManifestSignature,
  windowStartFor,
} from './crypto';

/**
 * Known-answer vectors produced by the BACKEND (`offline-ticket-crypto.test.ts`
 * in C1RCLE-BACKEND, generated by an independent node:crypto script). If these
 * fail, this device and the server no longer agree on which tickets are genuine.
 */
const KAT = {
  ticketKey: '09442d07af416089ff006c63380f5b19cca1d27782509dbcf53dfd4e7d9f0b62',
  signature: 'd83a16a83871f0d0aaafb8fb4049a70d4afefbbadf934cbcb31aebd021a938c5',
  window: 1_700_000_010,
  publicKey: 'MtUqNKj9Q6R8rL8SRtgQ6swSb3iEl9M540w2gvh2NUw=',
  manifestSignature:
    'WjIEdcujbhVC+foySz5O9rgMcyCr5Ovb5dZebx3KqWhauQVryRgZrm71Mfn4HMjwkbzMvEkLJVaHvzGVOcASAg==',
};
const ID = 'ENT-kat-1';
const MANIFEST = {
  eventId: 'evt_kat',
  signedAt: '2026-10-18T10:00:00.000Z',
  expiresAt: '2026-10-18T22:00:00.000Z',
  entries: [
    {
      entitlementId: ID,
      validFrom: '2026-10-18T10:00:00.000Z',
      validTo: '2026-10-18T22:00:00.000Z',
      seatsRemaining: 2,
      ticketKey: KAT.ticketKey,
    },
  ],
};

describe('server known-answer vectors', () => {
  it('verifies the rotating code the server signed', () => {
    const parsed = parseRotatingQr(`${ID}:${String(KAT.window)}:${KAT.signature}`);
    expect(parsed).not.toBeNull();
    if (parsed === null) return;
    expect(checkRotatingQr({ ticketKey: KAT.ticketKey, parsed, atMs: 1_700_000_015_000 })).toBe(
      true,
    );
  });

  it('verifies the Ed25519 manifest signature the server produced', () => {
    expect(verifyManifestSignature(KAT.publicKey, MANIFEST, KAT.manifestSignature)).toBe(true);
  });

  const tamperings: [string, typeof MANIFEST][] = [
    [
      'a swapped ticket key',
      {
        ...MANIFEST,
        entries: [{ ...MANIFEST.entries[0], ticketKey: 'f'.repeat(64) }] as typeof MANIFEST.entries,
      },
    ],
    [
      'more seats than signed',
      {
        ...MANIFEST,
        entries: [{ ...MANIFEST.entries[0], seatsRemaining: 9 }] as typeof MANIFEST.entries,
      },
    ],
    ['another event', { ...MANIFEST, eventId: 'evt_other' }],
    ['a later expiry', { ...MANIFEST, expiresAt: '2030-01-01T00:00:00.000Z' }],
  ];
  for (const [label, tampered] of tamperings) {
    it(`rejects ${label}`, () => {
      expect(verifyManifestSignature(KAT.publicKey, tampered, KAT.manifestSignature)).toBe(false);
    });
  }

  it('never throws on malformed keys or signatures', () => {
    expect(verifyManifestSignature('not base64 !!', MANIFEST, KAT.manifestSignature)).toBe(false);
    expect(verifyManifestSignature(KAT.publicKey, MANIFEST, 'AAAA')).toBe(false);
    expect(verifyManifestSignature('', MANIFEST, '')).toBe(false);
  });
});

describe('rotating code timing', () => {
  const parsed = parseRotatingQr(`${ID}:${String(KAT.window)}:${KAT.signature}`);
  if (parsed === null) throw new Error('vector must parse');
  const base = (KAT.window + 5) * 1000;

  it('accepts within the window and one window either side, rejects a screenshot replay', () => {
    expect(checkRotatingQr({ ticketKey: KAT.ticketKey, parsed, atMs: base + 40_000 })).toBe(true);
    const late = base + (MAGIC_WINDOW_SEC * 3 + 1) * 1000;
    expect(checkRotatingQr({ ticketKey: KAT.ticketKey, parsed, atMs: late })).toBe(false);
    const early = base - (MAGIC_WINDOW_SEC * 3 + 1) * 1000;
    expect(checkRotatingQr({ ticketKey: KAT.ticketKey, parsed, atMs: early })).toBe(false);
  });

  it('rejects another ticket key and a flipped signature digit', () => {
    expect(checkRotatingQr({ ticketKey: 'a'.repeat(64), parsed, atMs: base })).toBe(false);
    const flipped = parsed.signature.endsWith('0') ? '1' : '0';
    const forged = { ...parsed, signature: parsed.signature.slice(0, -1) + flipped };
    expect(checkRotatingQr({ ticketKey: KAT.ticketKey, parsed: forged, atMs: base })).toBe(false);
  });

  it('parses only the three-part rotating shape', () => {
    expect(parseRotatingQr('ENT-1')).toBeNull();
    expect(parseRotatingQr('a:b')).toBeNull();
    expect(parseRotatingQr('a::c')).toBeNull();
    expect(parseRotatingQr('a:xyz:c')?.windowStart).toBeNull();
    expect(windowStartFor(1_700_000_015_000)).toBe(KAT.window);
  });
});
